    generatorVersion: obx_int.GeneratorVersion.v2025_12_16,
    entities: _entities,
    lastEntityId: const obx_int.IdUid(25, 8392231438185125594),
    lastIndexId: const obx_int.IdUid(1, 8294754535911300021),
    lastRelationId: const obx_int.IdUid(0, 0),
    lastSequenceId: const obx_int.IdUid(0, 0),
    retiredEntityUids: const [],
    retiredIndexUids: const [],
    retiredPropertyUids: const [],
    retiredRelationUids: const [],
    modelVersion: 5,
    modelVersionParserMinimum: 5,
    version: 1,
  );

  final bindings = <Type, obx_int.EntityDefinition>{
    Achievement: obx_int.EntityDefinition<Achievement>(
      model: _entities[0],
      toOneRelations: (Achievement object) => [],
      toManyRelations: (Achievement object) => {},
      getId: (Achievement object) => object.id,
      setId: (Achievement object, int id) {
        object.id = id;
      },
      objectToFB: (Achievement object, fb.Builder fbb) {
        final achievementIdOffset = fbb.writeString(object.achievementId);
        final titleOffset = fbb.writeString(object.title);
        final descriptionOffset = fbb.writeString(object.description);
        final iconPathOffset = fbb.writeString(object.iconPath);
        fbb.startTable(11);
        fbb.addInt64(0, object.id);
        fbb.addOffset(1, achievementIdOffset);
        fbb.addOffset(2, titleOffset);
        fbb.addOffset(3, descriptionOffset);
        fbb.addOffset(4, iconPathOffset);
        fbb.addInt64(5, object.unlockedAt?.millisecondsSinceEpoch);
        fbb.addBool(6, object.isUnlocked);
        fbb.addFloat64(7, object.progress);
        fbb.addFloat64(8, object.targetValue);
        fbb.addFloat64(9, object.currentValue);
        fbb.finish(fbb.endTable());
        return object.id;
      },
      objectFromFB: (obx.Store store, ByteData fbData) {
        final buffer = fb.BufferContext(fbData);
        final rootOffset = buffer.derefObject(0);
        final unlockedAtValue = const fb.Int64Reader().vTableGetNullable(
          buffer,
          rootOffset,
          14,
        );
        final idParam = const fb.Int64Reader().vTableGet(
          buffer,
          rootOffset,
          4,
          0,
        );
        final achievementIdParam = const fb.StringReader(
          asciiOptimization: true,
        ).vTableGet(buffer, rootOffset, 6, '');
        final titleParam = const fb.StringReader(
          asciiOptimization: true,
        ).vTableGet(buffer, rootOffset, 8, '');
        final descriptionParam = const fb.StringReader(
          asciiOptimization: true,
        ).vTableGet(buffer, rootOffset, 10, '');
        final iconPathParam = const fb.StringReader(
          asciiOptimization: true,
        ).vTableGet(buffer, rootOffset, 12, '');
        final unlockedAtParam = unlockedAtValue == null
